const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Paris geometry
  const paris = ee.Geometry.Point([2.3522, 48.8566]);
  const parisRegion = paris.buffer(10000); // 10km radius around Paris center

  // 2. Define time range - August 6, 2024, allowing some flexibility for satellite overpass
  const targetDate = '2024-08-06';
  const startDate = '2024-08-06';
  const endDate = '2024-08-07';

  console.log('Searching for LST data on August 6, 2024 in Paris...');

  // 3. Try MODIS Aqua first (daytime overpass ~1:30 PM local)
  let collection = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(paris)
    .select('LST_Day_1km', 'QC_Day');

  let collectionSize = collection.size().getInfo();
  console.log(`MODIS Aqua images found: ${collectionSize}`);

  // 4. Fallback to MODIS Terra if Aqua not available
  if (collectionSize === 0) {
    console.log('Trying MODIS Terra...');
    collection = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(paris)
      .select('LST_Day_1km', 'QC_Day');

    collectionSize = collection.size().getInfo();
    console.log(`MODIS Terra images found: ${collectionSize}`);
  }

  // 5. Try Landsat 8/9 as final fallback
  if (collectionSize === 0) {
    console.log('Trying Landsat 8/9...');
    const landsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterDate(startDate, endDate)
      .filterBounds(paris)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));

    collectionSize = landsat.size().getInfo();
    console.log(`Landsat images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('No images found for the specified date and location.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  if (collectionSize === 0) {
    console.log('No data available for August 6, 2024.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Process MODIS LST data
  const image = collection.first();

  // Apply quality mask for MODIS
  const qaMask = image.select('QC_Day').bitwiseAnd(3).lte(1); // Mandatory QA flags
  const lstMasked = image.select('LST_Day_1km').updateMask(qaMask);

  // 7. Check for valid pixels
  const pixelCount = lstMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: parisRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Valid pixels after masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Calculate statistics - MODIS LST is in Kelvin * 0.02
  const stats = lstMasked.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: parisRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanLSTKelvin = stats.get('LST_Day_1km_mean').getInfo();
  const maxLSTKelvin = stats.get('LST_Day_1km_max').getInfo();

  if (meanLSTKelvin === null || maxLSTKelvin === null) {
    console.log('Calculation failed - no valid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert from MODIS scale (Kelvin * 0.02) to Celsius
  const meanLSTCelsius = (meanLSTKelvin * 0.02) - 273.15;
  const maxLSTCelsius = (maxLSTKelvin * 0.02) - 273.15;

  console.log(`Mean LST: ${meanLSTCelsius.toFixed(2)}°C`);
  console.log(`Max LST: ${maxLSTCelsius.toFixed(2)}°C`);
  console.log(`Threshold: 32°C`);

  // Validate reasonable temperature range
  if (meanLSTCelsius < -50 || meanLSTCelsius > 70 || maxLSTCelsius < -50 || maxLSTCelsius > 70) {
    console.log('Temperature values out of reasonable range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Final answer - check if temperatures exceeded 32°C
  if (maxLSTCelsius > 32) {
    console.log('Land surface temperatures exceeded 32°C.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Land surface temperatures did not exceed 32°C.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
